<?php require "db.php";$pageTitle="Vehicles";$msg="";if($_SERVER["REQUEST_METHOD"]==="POST"){$n=trim($_POST["vehicle_number"]??"");$ty=trim($_POST["vehicle_type"]??"");$cap=(float)($_POST["capacity"]??0);$st=$_POST["status"]??"Available";if($n&&$ty&&$cap>0){$s=$conn->prepare("INSERT INTO vehicles(vehicle_number,vehicle_type,capacity,status) VALUES(?,?,?,?)");$s->bind_param("ssds",$n,$ty,$cap,$st);$msg=$s->execute()?"Vehicle added successfully.":"Could not add vehicle; number may already exist.";}else $msg="Complete all fields.";}$list=$conn->query("SELECT * FROM vehicles ORDER BY id DESC");include "includes/header.php";?><div class="page-head"><div><p class="eyebrow">FLEET DIRECTORY</p><h1>Vehicles</h1><p>Register vehicles and monitor availability.</p></div></div><?php if($msg):?><p class="notice"><?=htmlspecialchars($msg)?></p><?php endif;?><section class="panel"><h2>Add vehicle</h2><form method="post" class="form-grid"><label>Vehicle number<input name="vehicle_number" placeholder="MH10AB1234" required></label><label>Vehicle type<input name="vehicle_type" placeholder="Truck / Van / Tempo" required></label><label>Capacity (tonnes)<input type="number" name="capacity" min=".1" step=".1" required></label><label>Status<select name="status"><option>Available</option><option>On Trip</option><option>In Maintenance</option></select></label><button class="button">Add vehicle</button></form></section><section class="panel"><h2>Vehicle list</h2><?php if($list&&$list->num_rows):?><div class="table-wrap"><table><tr><th>Number</th><th>Type</th><th>Capacity</th><th>Status</th></tr><?php while($x=$list->fetch_assoc()):?><tr><td><?=htmlspecialchars($x["vehicle_number"])?></td><td><?=htmlspecialchars($x["vehicle_type"])?></td><td><?=$x["capacity"]?> t</td><td><span class="badge"><?=htmlspecialchars($x["status"])?></span></td></tr><?php endwhile;?></table></div><?php else:?><p class="muted">No vehicles registered yet.</p><?php endif;?></section><?php include "includes/footer.php";?>